SINA_SMART["semio-gi-diarrhoea"] = {"lecture":"semio-gi-diarrhoea","title":"Diarrhoea","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"semio-gi-diarrhoea:e0","text":"Diarrhoea: > 300 g/day, > 3 stools/day, > 90% water.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e1","text":"Acute < 2 weeks; prolonged 2-4 weeks; chronic > 4 weeks.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e2","text":"Choleriform: toxin, watery, persists fasting. Dysenteric: invasive, blood, fever, tenesmus.","topic":"Acute diarrhoea","sec":1,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e3","text":"Dangerous in infants, elderly, immunocompromised.","topic":"Acute diarrhoea","sec":1,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e4","text":"Antibiotics → think C. difficile.","topic":"Acute diarrhoea","sec":1,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e5","text":"Tests in acute diarrhoea only if severe, bloody, febrile, > 3 days, epidemic or immunosuppressed.","topic":"Acute diarrhoea","sec":1,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e6","text":"Digital rectal examination is mandatory in chronic diarrhoea.","topic":"Chronic diarrhoea: approach","sec":2,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e7","text":"Anti-transglutaminase antibodies and duodenal biopsies for coeliac disease.","topic":"Chronic diarrhoea: approach","sec":2,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e10","text":"Exudative diarrhoea: alpha-1 antitrypsin clearance.","topic":"Chronic diarrhoea: mechanisms","sec":3,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e8","text":"Osmotic and motor stop/improve with fasting; secretory persists.","topic":"Chronic diarrhoea: mechanisms","sec":3,"importance":"core","highYield":"untested"},{"id":"semio-gi-diarrhoea:e9","text":"Malabsorption: greasy, pale, foul stools.","topic":"Chronic diarrhoea: mechanisms","sec":3,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"4v07lr":"a","nzl2vm":"a","93rtbi":"a","15ut50c":"a","1j7d1q3":"a","1bonn2k":"a","1sbvzrw":"a","cizso3":"a","1ctr15h":"a","kezt57":"a","1i63i5q":"a","hxbdk8":"a","low8kp":"a","1k1gze0":"a","mwunxa":"a","xt0x5e":"a","1mecybk":"a","ceficq":"a","x7fx0w":"a","izdkv0":"a","b1wkgs":"a","oklo2p":"a","8ujid5":"a","17dtu2h":"a","4b583k":"a","ubahgd":"x"},"mapCounts":{"verified":0,"auto":25,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"semio-gi-diarrhoea:e0":{"s":0,"u":["Diarrhoea: > 300 g/day, > 3 stools/day, > 90% water.","Diarrhoea is the passage of loose or watery stools with more frequency and/or volume: over 300 g/day, more than 3 per day, over 90% water .","Differential diagnoses : false diarrhoea (small hard stools, under 300 g/day), anal incontinence, non-faecal discharge (blood, pus, mucus without stool)."],"dp":[]},"semio-gi-diarrhoea:e1":{"s":0,"u":["Acute < 2 weeks; prolonged 2-4 weeks; chronic > 4 weeks.","By duration: acute (under 2 weeks: infection, food poisoning), prolonged (2 to 4 weeks: post-infectious, parasitic), chronic (over 4 weeks: IBD, coeliac disease, pancreatic insufficiency)."],"dp":[]},"semio-gi-diarrhoea:e2":{"s":1,"u":["Choleriform: toxin, watery, persists fasting. Dysenteric: invasive, blood, fever, tenesmus.","Two mechanisms: secretory (choleriform) : an enterotoxin drives massive water and salt secretion (cholera, enterotoxigenic E. coli), profuse watery stools, dehydration, persists during fasting ; invasive (dysenteric) : mucosal invasion (Shigella, Salmonella, Campylobacter), bloody mucous stools, fever, pain, tenesmus ."],"dp":[{"h":"Why dysenteric stools contain blood","t":"Invasive bacteria penetrate and destroy the colonic mucosa, producing ulcers that bleed and inflammatory exudate rich in mucus and pus. Inflammation of the rectum also causes tenesmus, the painful urge to pass stool with little output. Toxin-mediated diarrhoea leaves the mucosa intact, which is why it is watery rather than bloody. Source: the lecture's pathophysiological types slide."}]},"semio-gi-diarrhoea:e3":{"s":1,"u":["Dangerous in infants, elderly, immunocompromised.","Very frequent, usually benign and self-limiting, but dangerous in infants, the elderly and the immunocompromised , and sometimes reveals a chronic disease."],"dp":[]},"semio-gi-diarrhoea:e4":{"s":1,"u":["Antibiotics → think C. difficile.","Orientation : recent meals, collective cases, tropical travel, antibiotics (C. difficile) , HIV or chemotherapy; stool frequency, volume, blood or pus; vomiting, pain, tenesmus."],"dp":[]},"semio-gi-diarrhoea:e5":{"s":1,"u":["Tests in acute diarrhoea only if severe, bloody, febrile, > 3 days, epidemic or immunosuppressed.","Tests only if : severe dehydration, blood or pus, fever over 38 °C, duration over 3 days , epidemic context or immunosuppression: CBC, CRP, electrolytes, renal function; stool culture and parasitology; CT or colonoscopy if complicated."],"dp":[]},"semio-gi-diarrhoea:e6":{"s":2,"u":["Digital rectal examination is mandatory in chronic diarrhoea.","Examination : hydration and nutrition, abdomen, mandatory digital rectal exam , extra-abdominal signs (nodes, skin, joints, eyes, thyroid)."],"dp":[]},"semio-gi-diarrhoea:e7":{"s":2,"u":["Anti-transglutaminase antibodies and duodenal biopsies for coeliac disease.","Tests : first line CBC, CRP, electrolytes, liver tests, protein electrophoresis, calcium, vitamin D, ferritin, albumin (severity, malabsorption); second line TSH, HIV serology, anti-transglutaminase antibodies , stool parasitology; endoscopy: gastroscopy with duodenal biopsies , colonoscopy with ileal and colonic biopsies (IBD, coeliac, microscopic colitis); imaging: ultrasound, CT enterography, MRI."],"dp":[]},"semio-gi-diarrhoea:e10":{"s":3,"u":["Exudative diarrhoea: alpha-1 antitrypsin clearance.","Exudative : plasma protein loss into the gut, diagnosed by alpha-1 antitrypsin clearance ; lymphangiectasia, lymphoma, cirrhosis, ulcerative colitis."],"dp":[]},"semio-gi-diarrhoea:e8":{"s":3,"u":["Osmotic and motor stop/improve with fasting; secretory persists.","Motor : accelerated transit; post-prandial, urgent, improves with fasting; hyperthyroidism, diabetes, carcinoid tumour, gastrectomy, IBS.","Osmotic : osmotically active substances (mannitol, lactulose, laxatives, lactase deficiency ); stops with fasting ; no blood, no general deterioration."],"dp":[{"h":"Why the fasting test separates osmotic from secretory diarrhoea","t":"Osmotic diarrhoea is caused by something the patient eats that stays in the lumen and holds water; stop eating and the water stops. Secretory diarrhoea comes from the gut wall actively pumping out salt and water, driven by a toxin, hormone or inflammation, which continues regardless of food. That simple observation narrows the list of causes dramatically. Source: the lecture's synthetic comparison table."}]},"semio-gi-diarrhoea:e9":{"s":3,"u":["Malabsorption: greasy, pale, foul stools.","Malabsorptive : abundant, greasy, pale, foul-smelling stools; weight loss, anaemia, bone pain, brittle nails; small-bowel disease (coeliac, Crohn's, Whipple, lymphoma, giardiasis), pancreatic insufficiency, bile-salt deficiency."],"dp":[]}},"meta":{"4v07lr":{"a":"recall","vg":"semio-gi-diarrhoea:e0/recall/1"},"nzl2vm":{"a":"recall","vg":"semio-gi-diarrhoea:e1/recall/1"},"93rtbi":{"a":"recall","vg":"semio-gi-diarrhoea:e0/recall/2"},"15ut50c":{"a":"relationship","vg":"semio-gi-diarrhoea:e2/relationship/1"},"1j7d1q3":{"a":"recall","vg":"semio-gi-diarrhoea:e2/recall/1"},"1bonn2k":{"a":"recall","vg":"semio-gi-diarrhoea:e4/recall/1"},"1sbvzrw":{"a":"recall","vg":"semio-gi-diarrhoea:e5/recall/1"},"cizso3":{"a":"recall","vg":"semio-gi-diarrhoea:e8/recall/1"},"1ctr15h":{"a":"recall","vg":"semio-gi-diarrhoea:e9/recall/1"},"kezt57":{"a":"relationship","vg":"semio-gi-diarrhoea:e8/relationship/1"},"1i63i5q":{"a":"recall","vg":"semio-gi-diarrhoea:e10/recall/1"},"hxbdk8":{"a":"recall","vg":"semio-gi-diarrhoea:e7/recall/1"},"low8kp":{"a":"recall","vg":"semio-gi-diarrhoea:e7/recall/2"},"1k1gze0":{"a":"recall","vg":"semio-gi-diarrhoea:e0/recall/1"},"mwunxa":{"a":"recall","vg":"semio-gi-diarrhoea:e0/recall/2"},"xt0x5e":{"a":"relationship","vg":"semio-gi-diarrhoea:e2/relationship/1"},"1mecybk":{"a":"recall","vg":"semio-gi-diarrhoea:e2/recall/2"},"ceficq":{"a":"recall","vg":"semio-gi-diarrhoea:e4/recall/1"},"x7fx0w":{"a":"recall","vg":"semio-gi-diarrhoea:e5/recall/1"},"izdkv0":{"a":"recall","vg":"semio-gi-diarrhoea:e6/recall/1"},"b1wkgs":{"a":"recall","vg":"semio-gi-diarrhoea:e7/recall/1"},"oklo2p":{"a":"recall","vg":"semio-gi-diarrhoea:e8/recall/1"},"8ujid5":{"a":"recall","vg":"semio-gi-diarrhoea:e9/recall/1"},"17dtu2h":{"a":"recall","vg":"semio-gi-diarrhoea:e8/recall/1"},"4b583k":{"a":"recall","vg":"semio-gi-diarrhoea:e10/recall/1"}},"explRev":"981f49283cfa"};
